type LogoVariant = 'onLight' | 'onDark';

interface LogoProps {
  variant: LogoVariant;
  className?: string;
}

// Intrinsic size of public/brand/vn-one-logo-*.webp, generated by
// scripts/build-brand-assets.mjs at a height of 96px.
const LOGO_WIDTH = 194;
const LOGO_HEIGHT = 96;

const LOGO_SRC: Record<LogoVariant, string> = {
  onLight: '/brand/vn-one-logo-dark.webp',
  onDark: '/brand/vn-one-logo-chrome.webp',
};

export default function Logo({ variant, className }: LogoProps) {
  return (
    <img
      src={LOGO_SRC[variant]}
      alt="VN One"
      width={LOGO_WIDTH}
      height={LOGO_HEIGHT}
      decoding="async"
      className={className}
    />
  );
}
